#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

die() { printf '\n  %s✗ %s%s\n\n' "$RED" "$1" "$RESET"; exit 1; }

cd "$(dirname "$0")/.."
command -v gh >/dev/null 2>&1 || die "Install the GitHub CLI first: https://cli.github.com"
command -v node >/dev/null 2>&1 || die "Install Node.js first: https://nodejs.org"
gh auth status >/dev/null 2>&1 || die "Sign in to GitHub first: gh auth login"

REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
BRANCH=$(gh repo view --json defaultBranchRef --jq .defaultBranchRef.name)
[[ $(gh repo view --json viewerPermission --jq .viewerPermission) == ADMIN ]] \
  || die "You need admin access to $REPO to set secrets and rulesets."

RULESET_FILE=.github/rulesets/main.json
RULESET_NAME=$(node -p "require('./$RULESET_FILE').name")
REQUIRED_CHECK=$(node -p "require('./$RULESET_FILE').rules.find((rule) => rule.type === 'required_status_checks').parameters.required_status_checks[0].context")

TOTAL_STAGES=3

banner "Taskly Test Agent: GitHub setup for $REPO"

# ──────────────────────────────────────────────────────────────────────────
stage "Model credential"
say "The Test Agent job needs one Anthropic credential, stored as a repo secret."
say "  1) Anthropic API key           → ANTHROPIC_API_KEY (billed per use; use this for shared repos)"
say "  2) Claude subscription token   → CLAUDE_CODE_OAUTH_TOKEN (Pro/Max/Team/Enterprise; tied to your account)"
CHOICE=""
until [[ "$CHOICE" == 1 || "$CHOICE" == 2 ]]; do ask CHOICE "Which one do you have? [1/2]"; done

if [[ "$CHOICE" == 1 ]]; then
  SECRET_NAME=ANTHROPIC_API_KEY; OTHER_SECRET=CLAUDE_CODE_OAUTH_TOKEN
  open_url "https://console.anthropic.com/settings/keys"
  step "Click 'Create Key', name it (for example taskly-test-agent), then copy the key."
else
  SECRET_NAME=CLAUDE_CODE_OAUTH_TOKEN; OTHER_SECRET=ANTHROPIC_API_KEY
  step "In another terminal, run: claude setup-token"
  step "Sign in with your Claude subscription in the browser it opens."
  step "Copy the token it prints."
fi

EXISTING_SECRETS=$(gh secret list --json name --jq '.[].name')
has_secret() { grep -qxF "$1" <<<"$EXISTING_SECRETS"; }
has_secret "$SECRET_NAME" && note "$SECRET_NAME is already set. Press Enter to keep it."

while :; do
  ask_secret CREDENTIAL "Paste it here:"
  if [[ -n "$CREDENTIAL" ]]; then set_secret "$SECRET_NAME" "$CREDENTIAL"; break; fi
  if has_secret "$SECRET_NAME"; then note "kept the existing $SECRET_NAME"; break; fi
  warn "Nothing pasted. Try again."
done

if has_secret "$OTHER_SECRET"; then
  warn "$OTHER_SECRET is also set. Keep one credential so it's clear which one the agent uses."
  if confirm "Delete $OTHER_SECRET?"; then
    gh secret delete "$OTHER_SECRET" >/dev/null
    printf '  %s✓ deleted%s GitHub secret %s\n' "$GREEN" "$RESET" "$OTHER_SECRET"
  else
    SKIPPED+=("delete GitHub secret $OTHER_SECRET: gh secret delete $OTHER_SECRET")
  fi
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Ruleset on $BRANCH"
say "Applies $RULESET_FILE ('$RULESET_NAME') to $BRANCH:"
step "changes land only through pull requests"
step "the $REQUIRED_CHECK status must pass before a merge"
step "force-pushes are blocked"
note "Nobody bypasses it, admins included. Re-running updates the same ruleset."

RULESET_ID=$(gh api "repos/$REPO/rulesets" \
  --jq ".[] | select(.source_type == \"Repository\" and .name == \"$RULESET_NAME\") | .id" | head -n1)

if confirm "Apply it now?"; then
  if [[ -n "$RULESET_ID" ]]; then
    gh api --method PUT "repos/$REPO/rulesets/$RULESET_ID" --input "$RULESET_FILE" >/dev/null
    printf '  %s✓ updated%s ruleset %s\n' "$GREEN" "$RESET" "$RULESET_NAME"
  else
    gh api --method POST "repos/$REPO/rulesets" --input "$RULESET_FILE" >/dev/null
    printf '  %s✓ created%s ruleset %s\n' "$GREEN" "$RESET" "$RULESET_NAME"
  fi
else
  SKIPPED+=("ruleset $RULESET_NAME: re-run this wizard")
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Check rules"
say "Rules GitHub now enforces on $BRANCH:"
RULE_TYPES=$(gh api "repos/$REPO/rules/branches/$BRANCH" --jq '.[].type')
REQUIRED_CHECKS=$(gh api "repos/$REPO/rules/branches/$BRANCH" \
  --jq '.[] | select(.type == "required_status_checks") | .parameters.required_status_checks[].context')

# check_enforced LABEL LIST ITEM reports whether ITEM is a line of LIST.
check_enforced() {
  if grep -qxF "$3" <<<"$2"; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"
  else
    printf '  %s✗%s %s\n' "$RED" "$RESET" "$1"
    SKIPPED+=("not enforced: $1")
  fi
}
check_enforced "direct pushes to $BRANCH are rejected (pull request required)" "$RULE_TYPES" pull_request
check_enforced "a PR cannot merge until $REQUIRED_CHECK passes" "$REQUIRED_CHECKS" "$REQUIRED_CHECK"
check_enforced "force-pushes to $BRANCH are blocked" "$RULE_TYPES" non_fast_forward
note "To see it live, open a PR with a failing test: the merge button stays blocked."
pause

finish
